size_t js_v07c_timing_plan_count(void) { return sizeof(PLANS)/sizeof(PLANS[0]); }
const JSV07TimingPlan *js_v07c_timing_plan(uint32_t key) {
 size_t lo=0,hi=js_v07c_timing_plan_count();
 while(lo<hi){size_t m=lo+(hi-lo)/2;if(PLANS[m].key<key)lo=m+1;else hi=m;}
 return lo<js_v07c_timing_plan_count()&&PLANS[lo].key==key?&PLANS[lo]:0;
}
